const CLAVE="pendientes-tareas",form=document.getElementById("form"),texto=document.getElementById("texto"),lista=document.getElementById("lista"),vacio=document.getElementById("vacio"),resumen=document.getElementById("resumen"),botonesFiltro=document.querySelectorAll("[data-filtro]");let tareas=cargar(),filtro="todas";function cargar(){try{return JSON.parse(localStorage.getItem(CLAVE))||[]}catch(t){return[]}}function guardar(){try{localStorage.setItem(CLAVE,JSON.stringify(tareas))}catch(t){}}function visibles(){return"pendientes"===filtro?tareas.filter(t=>!t.hecha):"hechas"===filtro?tareas.filter(t=>t.hecha):tareas}function pintar(){lista.innerHTML="";const t=visibles();t.forEach(t=>{const e=document.createElement("li");t.hecha&&(e.className="hecha");const a=document.createElement("input");a.type="checkbox",a.checked=t.hecha,a.setAttribute("aria-label","Marcar como hecha: "+t.texto),a.addEventListener("change",()=>{t.hecha=a.checked,guardar(),pintar()});const r=document.createElement("span");r.textContent=t.texto;const n=document.createElement("button");n.type="button",n.className="borrar",n.textContent="Borrar",n.setAttribute("aria-label","Borrar tarea: "+t.texto),n.addEventListener("click",()=>{tareas=tareas.filter(e=>e.id!==t.id),guardar(),pintar()}),e.append(a,r,n),lista.appendChild(e)}),vacio.hidden=t.length>0;const e=tareas.filter(t=>!t.hecha).length;resumen.textContent=tareas.length?e+" pendiente(s) de "+tareas.length+" tarea(s)":""}form.addEventListener("submit",t=>{t.preventDefault();const e=texto.value.trim();e&&(tareas.push({id:Date.now(),texto:e,hecha:!1}),texto.value="",guardar(),pintar())}),botonesFiltro.forEach(t=>t.addEventListener("click",()=>{filtro=t.dataset.filtro,botonesFiltro.forEach(e=>e.classList.toggle("activo",e===t)),pintar()})),document.getElementById("limpiar").addEventListener("click",()=>{tareas=tareas.filter(t=>!t.hecha),guardar(),pintar()}),pintar();